package edu.ku.commerce.omnichannel_commerce.inventory;
import java.time.*; import java.util.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*;
@Service @Transactional public class InventoryServiceImpl implements InventoryService { private final StockRepository stocks; private final ReservationRepository reservations; public InventoryServiceImpl(StockRepository s,ReservationRepository r){stocks=s;reservations=r;}
 public void reserve(Long orderId,Long productId,int quantity,Location location){ Stock s=stocks.lockByProductIdAndLocation(productId,location).orElseThrow(()->new IllegalArgumentException("No stock for product")); if(quantity<1||s.getAvailable()<quantity) throw new IllegalStateException("Insufficient inventory"); s.setAvailable(s.getAvailable()-quantity);s.setReserved(s.getReserved()+quantity); Reservation r=new Reservation();r.setOrderId(orderId);r.setProductId(productId);r.setLocation(location);r.setQuantity(quantity);r.setExpiresAt(Instant.now().plusSeconds(900));reservations.save(r); }
 public void commit(Long orderId){reservations.findByOrderId(orderId).stream().filter(r->r.getState()==Reservation.State.ACTIVE).forEach(r->{r.setState(Reservation.State.COMMITTED);Stock s=stocks.lockByProductIdAndLocation(r.getProductId(),r.getLocation()).orElseThrow();s.setReserved(s.getReserved()-r.getQuantity());});}
 public void release(Long orderId){reservations.findByOrderId(orderId).stream().filter(r->r.getState()==Reservation.State.ACTIVE).forEach(r->{r.setState(Reservation.State.RELEASED);Stock s=stocks.lockByProductIdAndLocation(r.getProductId(),r.getLocation()).orElseThrow();s.setReserved(s.getReserved()-r.getQuantity());s.setAvailable(s.getAvailable()+r.getQuantity());});}
 @Transactional(readOnly=true) public List<Stock> stock(Long productId){return stocks.findByProductId(productId);}}
